/// @brief CUSUM change detector
/// (`[iu, il, us, ls] = cusum(x, climit, mshift, tmean, tdev)`).
/// 
/// Standardises `x` to `(x - tmean) / tdev`, accumulates the one-sided CUSUM
/// statistics with an `mshift/2` slack, and reports the first sample index at
/// which each one-sided sum first exceeds `climit`. The target mean / std
pub fn cusum(ctx: &Context, args: &[&Value]) -> Result<Value, Error> {
    let mut outs = ctx.call(TOOLBOX, "cusum", args, 1)?;
    Ok(outs.pop().unwrap())
}
pub fn cusum_n(ctx: &Context, args: &[&Value], nargout: usize) -> Result<Vec<Value>, Error> {
    ctx.call(TOOLBOX, "cusum", args, nargout)
}
/// Strongly-typed wrapper for `signal::cusum` generated from its C++ header.
pub fn cusum_typed(ctx: &Context, p_0_x: &Value, p_1_climit: f64, p_2_mshift: f64, p_3_tmean: &Value, p_4_tdev: &Value) -> Result<Value, Error> {
    let v_1 = (p_1_climit).into_numkit_value()?;
    let v_2 = (p_2_mshift).into_numkit_value()?;
    let mut outs = ctx.call(TOOLBOX, "cusum", &[p_0_x, &v_1, &v_2, p_3_tmean, p_4_tdev], 1)?;
    Ok(outs.pop().unwrap())
}

